   #&#x2F;bin&#x2F;sh
   read x;
   y=https:&#x2F;&#x2F;www.youtube.com&#x2F;youtubei&#x2F;v1&#x2F;player?prettyPrint=false 
   curl -K&#x2F;dev&#x2F;stdin $y &lt;&lt;eof|yy030|if test $# -gt 0;then egrep itag=$1;else yy082 f|uniq;fi;
   silent
